package com.bplus.share;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.widget.*;import org.json.*;
/** Explicit per-paired-device folder grant. Never migrates a global enable flag. */
public final class DeviceSettingsActivity extends Activity{
 private String id,key;private int generation;
 public static String key(String id){return "autoPeer_"+id+"_";}
 public static void open(Activity a,String id){a.startActivity(new Intent(a,DeviceSettingsActivity.class).putExtra("peer",id));}
 public void onCreate(Bundle b){super.onCreate(b);Ui.applyLocale(this);Ui.applyTheme(this);id=getIntent().getStringExtra("peer");if(id==null||Store.peerById(id)==null){finish();return;}key=key(id);build();}
 private void build(){JSONObject p=Store.peerById(id);if(p==null){finish();return;}LinearLayout root=Ui.col(this);root.setBackgroundColor(Ui.bg);root.addView(Ui.topBar(this,getString(R.string.device_settings),true,null));root.addView(Ui.sub(this,p.optString("name")));LinearLayout body=Ui.col(this);Ui.pad(body,18,18,18,18,this);root.addView(body);boolean on=Store.get(key+"on","0").equals("1");LinearLayout toggle=Ui.setRow(this,getString(R.string.autosend),getString(R.string.auto_device_note),getString(on?R.string.autosend_on:R.string.autosend_off));body.addView(toggle);toggle.setOnClickListener(v->{generation++;Store.set(key+"on","0");Net.cancelAuto(id);FileJobs.cancelWatched(id);if(on)build();else if(Store.get(key+"folder","").isEmpty())pick();else enable();});LinearLayout folder=Ui.setRow(this,getString(R.string.pick_folder),Store.get(key+"folder","").isEmpty()?getString(R.string.auto_no_folder):Store.get(key+"folder",""),"›");body.addView(folder);folder.setOnClickListener(v->{generation++;Store.set(key+"on","0");Net.cancelAuto(id);FileJobs.cancelWatched(id);pick();});body.addView(Ui.sub(this,getString(R.string.auto_ledger_note)));setContentView(root);}
 private void pick(){startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION),71);}
 public void onActivityResult(int q,int r,Intent data){super.onActivityResult(q,r,data);if(q!=71||r!=RESULT_OK||data==null||data.getData()==null){build();return;}Uri uri=data.getData();try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);Store.durable(key+"folder",uri.toString());enable();}catch(Exception e){fail();}}
 private void enable(){final String folder=Store.get(key+"folder","");final int g=++generation;new AppDialog(this).setTitle(R.string.autosend).setMessage(Store.peerById(id).optString("name")+"\n\n"+getString(R.string.autosend_consent)).setNegativeButton(R.string.cancel,(d,n)->build()).setPositiveButton(R.string.autosend_on,(d,n)->new Thread(()->{try{JSONArray files=AutoSend.listFilesChecked(this,Uri.parse(folder));AutoLedger.baseline(id+"|"+folder,files);runOnUiThread(()->{if(g==generation&&!isFinishing()&&Store.peerById(id)!=null&&folder.equals(Store.get(key+"folder",""))){try{Store.durable(key+"epoch",java.util.UUID.randomUUID().toString());Store.durable(key+"on","1");TransferService.start(this);build();}catch(Exception e){fail();}}});}catch(Exception e){runOnUiThread(this::fail);}}).start()).show();}
 private void fail(){Store.set(key+"on","0");Net.cancelAuto(id);FileJobs.cancelWatched(id);build();new AppDialog(this).setMessage(R.string.autosend_baseline_failed).setPositiveButton(android.R.string.ok,null).show();}
}
